def check(value, message):
    if not value:
        raise ValueError(message)


def verified_file(path, expected):
    path = Path(path).resolve(strict=True)
    check(expected and identity.sha(path) == expected, 'Changed identity file: ' + str(path))
    return path


def descriptor_inputs(descriptor):
    result = {}
    for key, value in descriptor.items():
        if key.endswith('File') and key + 'Sha256' in descriptor:
            result[key] = verified_file(value, descriptor[key + 'Sha256'])
    # Some existing descriptors use the shorter hash suffix for provenance/patch/source manifests.
    for field, digest in [('classpathManifestFile', 'classpathManifestSha256'),
                          ('sourceProvenanceFile', 'sourceProvenanceSha256'),
                          ('sourceManifestFile', 'sourceManifestSha256'),
                          ('originalSourceManifestFile', 'originalSourceManifestSha256'),
                          ('provenanceFile', 'provenanceSha256'),
                          ('productionPatchFile', 'productionPatchSha256')]:
        if field in descriptor:
            result[field] = verified_file(descriptor[field], descriptor[digest])
    return result


def validate_design(protocol):
    check(protocol['arms'] == ARMS and protocol['armDefinitions'] == ARM_DEFINITIONS,
          'Prespecified arms changed')
    check(protocol['balancedOrders'] == ORDERS and protocol['rounds'] == 6
          and protocol['warmup'] == 8 and protocol['iterations'] == 5,
          'Prespecified six-permutation 8+5 design changed')
    check(protocol['java'] == JAVA and protocol['jvmArguments'] == JVM,
          'Prespecified JVM changed')
    check(protocol['configuration'] == {
        'nativeEvaluation': True, 'directAdjacency': True, 'directAdjacencyMode': 'PREFER',
        'valueOverlay': False, 'forceSync': False, 'indexes': 'spoc,ospc,psoc,posc',
        'globalLedgerLimitBytes': 1073741824, 'perQueryLedgerLimitBytes': 268435456},
        'Prespecified store or memory configuration changed')
    check(protocol['statistics']['metrics'] == METRICS and protocol['timeoutSeconds'] == 240,
          'Prespecified analysis/deadline changed')


def make_candidate(base_path, original_descriptor, output):
    base_path = base_path.resolve(strict=True)
    base = json.loads(base_path.read_text())
    descriptor_inputs(base)
    original_cp, original_manifest = identity.original_identity()
    base_cp = Path(base['classpathFile']).read_text().strip()
    base_manifest = identity.classpath_manifest(base_cp)
    check(base_manifest == json.loads(Path(base['classpathManifestFile']).read_text())
          and len(base_manifest) == 127, 'Candidate base runtime identity mismatch')
    check(all(base_manifest[i] == original_manifest[i] for i in range(127) if i != 1),
          'Candidate base changed an entry other than production entry 1')
    provenance = json.loads(Path(base['provenanceFile']).read_text())
    check(provenance['name'] == 'frame-directory-guard' and provenance['unchangedOtherEntries'] == 126
          and provenance['replacedIndex'] == 1 and provenance['currentSourcesEqualEverySuccessfulValidation'],
          'Candidate is not the verified narrow frame guard')
    check(provenance['sourceRoleDeltaVersusMeasured']['production'] ==
          {'added': [], 'removed': [], 'changed': [PRODUCTION_PATH]}, 'Unexpected candidate production source delta')
    check(provenance['validationRecords'] and all(
          r['results']['tests'] > 0 and r['results']['failures'] == 0 and r['results']['errors'] == 0
          for r in provenance['validationRecords']), 'Candidate lacks passing source-matched validation')
    source_map = json.loads(Path(base['sourceManifestFile']).read_text())
    check(base['sourceIdentity'] == '15fe7d5011+followup-source-map-sha256-' + identity.canonical_sha(source_map),
          'Candidate source map does not match its identity')
    check(provenance['sourceIdentity'] == base['sourceIdentity'], 'Candidate provenance source mismatch')
    descriptor_inputs(original_descriptor)
    common_cp = Path(original_descriptor['classpathFile']).read_text().strip()
    common = identity.classpath_manifest(common_cp)
    check(len(common) == 128 and common[1:] == original_manifest and not original_descriptor['diagnosticOnly'],
          'Common uninstrumented v1 harness is not exact')
    output.mkdir(parents=True, exist_ok=False)
    cp = common[0]['path'] + os.pathsep + base_cp
    manifest = identity.classpath_manifest(cp)
    check(manifest[0] == common[0] and manifest[1:] == base_manifest,
          'Candidate overlay changed unexpected entries')
    (output / 'classpath.txt').write_text(cp + '\n')
    identity.write_new(output / 'classpath-manifest.json', manifest)
    result = dict(base)
    result.update({'name': 'frame-directory-guard-common-harness', 'diagnosticOnly': False,
        'productionSourceIdentity': base['sourceIdentity'],
        'sourceIdentity': base['sourceIdentity'] + '+namespace-harness-sha256-' + common[0]['sha256'],
        'classpathFile': str(output / 'classpath.txt'),
        'classpathFileSha256': identity.sha(output / 'classpath.txt'),
        'classpathManifestFile': str(output / 'classpath-manifest.json'),
        'classpathManifestSha256': identity.sha(output / 'classpath-manifest.json'),
        'baseCandidateDescriptorFile': str(base_path), 'baseCandidateDescriptorFileSha256': identity.sha(base_path),
        'sourceProvenanceFile': original_descriptor['sourceProvenanceFile'],
        'sourceProvenanceSha256': original_descriptor['sourceProvenanceSha256'],
        'harnessEntry': common[0], 'productionEntryIndex': 2,
        'nativeEvaluation': True, 'directAdjacencyEnabled': True})
    identity.write_new(output / 'runtime-descriptor.json', result)
    return result


def freeze_protocol(args):
    draft = json.loads(args.protocol.read_text())
    validate_design(draft)
    check(draft['status'] == 'draft-candidate-validation-required', 'Not an unfrozen frame-guard draft')
    common_path = Path(draft['commonHarnessDescriptorFile']).resolve(strict=True)
    check(identity.sha(common_path) == draft['commonHarnessDescriptorFileSha256'], 'Common descriptor changed')
    original = json.loads(common_path.read_text())
    base = json.loads(args.freeze_candidate.read_text())
    check(args.reviewed_production_patch_sha256
          and args.reviewed_production_patch_sha256 == base['productionPatchSha256'],
          'Candidate patch does not match the explicitly reviewed production patch hash')
    output = args.frozen_protocol.resolve()
    check(not output.exists(), 'Refusing to overwrite a frozen protocol')
    candidate = make_candidate(args.freeze_candidate, original, output.parent / 'candidate-runtime')
    draft.update({'status': 'frozen-ready', 'frozenEpochNs': time.time_ns(),
                  'driverSha256': identity.sha(Path(__file__)),
                  'identityHelperSha256': identity.sha(IDENTITY_FILE),
                  'reviewedProductionPatchSha256': args.reviewed_production_patch_sha256,
                  'freezeHelperFile': str(HERE.parent / 'freeze-candidate-runtime.py'),
                  'freezeHelperFileSha256': identity.sha(HERE.parent / 'freeze-candidate-runtime.py'),
                  'runtimes': {'original': original, 'candidate': candidate}})
    identity.write_new(output, draft)
    validate_protocol(output)
    print(json.dumps({'frozenProtocol': str(output), 'sha256': identity.sha(output), 'jvmsLaunched': 0}))


def validate_protocol(path):
    protocol = json.loads(path.read_text())
    validate_design(protocol)
    check(protocol['status'] == 'frozen-ready', 'Protocol is still a draft')
    verified_file(Path(__file__), protocol['driverSha256'])
    verified_file(IDENTITY_FILE, protocol['identityHelperSha256'])
    verified_file(protocol['freezeHelperFile'], protocol['freezeHelperFileSha256'])
    common_file = verified_file(protocol['commonHarnessDescriptorFile'],
                                protocol['commonHarnessDescriptorFileSha256'])
    check(protocol['runtimes']['original'] == json.loads(common_file.read_text()),
          'Original descriptor differs from the common v1 runtime')
    diagnostic = verified_file(protocol['diagnosticEvidenceFile'], protocol['diagnosticEvidenceFileSha256'])
    evidence = json.loads(diagnostic.read_text())
    check(evidence['resultValidity'] == 'passed' and evidence['targetQualified']
          and len(evidence['frameGuardEvidence']) == 4
          and all(q['allFrameRangesEnteredWithoutDirectory'] for q in evidence['frameGuardEvidence']),
          'Separate diagnostic did not establish target work')
    _, base = identity.original_identity()
    snapshots = {}
    for name in ('original', 'candidate'):
        desc = protocol['runtimes'][name]
        inputs = descriptor_inputs(desc)
        cp = inputs['classpathFile'].read_text().strip()
        manifest = identity.classpath_manifest(cp)
        check(len(manifest) == 128 and manifest == json.loads(inputs['classpathManifestFile'].read_text())
              and not desc.get('diagnosticOnly', False), 'Timing runtime identity mismatch: ' + name)
        if name == 'original':
            check(manifest[1:] == base and desc['productionSourceIdentity'] == identity.ORIGINAL_SOURCE,
                  'Original production/runtime is not exact')
        else:
            check(all(manifest[i + 1] == base[i] for i in range(127) if i != 1)
                  and manifest[2]['sha256'] != base[1]['sha256'], 'Candidate changed unexpected base entries')
            provenance = json.loads(inputs['provenanceFile'].read_text())
            check(provenance['name'] == 'frame-directory-guard'
                  and provenance['sourceIdentity'] == desc['productionSourceIdentity']
                  and provenance['currentSourcesEqualEverySuccessfulValidation']
                  and provenance['freezeHelperSha256'] == protocol['freezeHelperFileSha256']
                  and desc['productionPatchSha256'] == protocol['reviewedProductionPatchSha256'],
                  'Candidate validation provenance mismatch')
            check(desc['sourceIdentity'] == desc['productionSourceIdentity']
                  + '+namespace-harness-sha256-' + manifest[0]['sha256'], 'Candidate/harness source identity mismatch')
        snapshots[name] = {'classpath': cp, 'manifest': manifest, 'descriptor': desc, 'inputs': inputs}
    check(snapshots['candidate']['manifest'][0] == snapshots['original']['manifest'][0],
          'Timing arms do not share identical common harness bytes')
    for key in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS'):
        check(not os.environ.get(key), 'Unprescribed JVM environment: ' + key)
    return protocol, snapshots


def route_histogram(samples):
    histogram = Counter()
    for sample in samples:
        counters = sample['counters']
        signature = {'selections': sample['successfulSelections'],
            **{k: counters[k] for k in ('compiledBinds', 'interpretedBinds', 'aggregateCompiledBinds',
                                       'aggregateInterpretedBinds', 'semanticNativeCompiles')}}
        histogram[json.dumps(signature, sort_keys=True, separators=(',', ':'))] += 1
    return [{'signature': json.loads(k), 'count': v} for k, v in sorted(histogram.items())]


def normalized_metadata(metadata):
    result = dict(metadata)
    for key in ('arm', 'source', 'store'):
        result.pop(key, None)
    result['jvmArguments'] = [x for x in result['jvmArguments'] if not x.startswith('-D' + PROPERTY + '=')]
    result['systemProperties'] = {k: v for k, v in result['systemProperties'].items() if k != PROPERTY}
    return result


def validate_run(folder, arm, runtime, mode):
    records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines() if line.strip()]
    check(len(records) == 14 and records[0].get('type') == 'metadata', 'Expected metadata plus thirteen queries')
    metadata, samples = records[0], records[1:]
    check([s['iteration'] for s in samples] == list(range(-8, 5))
          and [s['stage'] for s in samples] == ['warmup'] * 8 + ['measurement'] * 5,
          'Unexpected query chronology')
    check(metadata['arm'] == arm and metadata['source'] == runtime['descriptor']['sourceIdentity'],
          'Source/arm identity mismatch')
    expected = {'canonicalGraphSha256': 'cf637a7e80dbd9468d7e8b04116da072f726038282dfab15380c267c8cc82e9b',
        'querySha256': '9cffa2dc37bbb1e2743442b228d5ab9a41115bf7c4a6667506231fbda3bfc301',
        'expectedRows': 1152000, 'expectedChecksum': '3123987218479850048', 'width': 12,
        'measurements': 100, 'readings': 10, 'statuses': 2, 'uniquePayloads': 0, 'consumption': 'full',
        'nativeEvaluation': True, 'directAdjacency': True, 'valueOverlay': False, 'forceSync': False,
        'directAdjacencyMode': 'PREFER', 'globalLedgerLimitBytes': 1073741824,
        'perQueryLedgerLimitBytes': 268435456,
        'indexes': 'spoc,ospc,psoc,posc', 'maxHeapBytes': 1073741824, 'warmup': 8,
        'measurementsToRun': 5, 'javaVersion': '25.0.5+8-LTS',
        'namespaceExperimentHarness': 'native-and-direct-adjacency-v1'}
    check(all(metadata.get(k) == v for k, v in expected.items()), 'Fixture/JVM/configuration differs')
    check(metadata['jvmArguments'] == JVM + ['-D' + PROPERTY + '=' + mode]
          and metadata['systemProperties'] == {'rdf4j.lmdb.hotCounters': 'true', PROPERTY: mode},
          'Unexpected JVM arguments, properties or instrumentation')
    setup = metadata['adjacencySetup']
    check(setup['state'] == 'ACTIVE' and setup['currentRevisionReady']
          and setup['appliedRevision'] == setup['currentDataRevision'], 'Adjacency not ready before queries')
    reasons = []
    for sample in samples:
        check(sample['type'] == 'sample' and sample['arm'] == arm and sample['valid'] and sample['complete']
              and sample['rows'] == 1152000 and sample['checksum'] == '3123987218479850048'
              and sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0
              and sample['ledgerReleased'] and all(sample[k] >= 0 for k in METRICS),
              'Invalid result, allocation, timing or unreleased ledger')
        counters, adjacency = sample['counters'], sample['adjacency']
        check(counters['semanticNativeCompiles'] == 1, 'Expected exactly one native compile per query')
        check(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
              and adjacency['appliedRevisionBefore'] == adjacency['currentRevisionBefore']
              == adjacency['appliedRevisionAfter'] == adjacency['currentRevisionAfter']
              == setup['currentDataRevision'], 'Adjacency revision/readiness changed')
        admissions = counters['coordinateAdmissions']
        check(admissions and admissions['opened'] == (1 if mode == 'dense' else 0)
              and admissions['initialAdmissionRefused'] == admissions['growthAdmissionRefused'] == 0,
              'Coordinate admission differs from the prescribed arm')
        if not (sample['autoRequested'] and sample['auto'] and sample['successfulSelections']
                and not any('forced' in item['mode'] for item in sample['successfulSelections'])
                and counters['irOpened'] == 1 and counters['irRows'] == 1152000
                and adjacency['lookupHits'] > 0):
            reasons.append('iteration %s: normal AUTO/native/adjacency target not observed' % sample['iteration'])
        if sample['stage'] == 'measurement' and not (counters['compiledBinds'] == 1
                and counters['interpretedBinds'] == counters['aggregateCompiledBinds']
                == counters['aggregateInterpretedBinds'] == 0):
            reasons.append('iteration %s: compiled-only measured IR not observed' % sample['iteration'])
    audit = json.loads((folder / 'root-host-audit.json').read_text())
    check(audit['format'] == 1 and audit['type'] == 'root-host-audit'
          and audit['readPhase'] == 'after-original-harness-main' and audit['harnessReturned']
          and audit['harnessFailureClass'] is None and audit['semanticNativeCompilesTotal']
          == sum(s['counters']['semanticNativeCompiles'] for s in samples) == 13,
          'Post-main root audit schema or compile reconciliation failed')
    if audit['hostedGenericTotal'] != 0:
        reasons.append('Generic outer root observed')
    validation = {'resultValidity': 'passed', 'targetQualified': not reasons, 'targetQualificationReasons': reasons,
                  'queryCount': len(samples), 'measuredQueryCount': 5,
                  'adjacencyInterpretation': 'Positive lookupHits establish successful query-time direct-adjacency use; not every result row or exclusively execution-phase access.'}
    identity.write_new(folder / 'validation.json', validation)
    return metadata, samples, audit, samples[8:], validation


def run_fork(command, folder, timeout):
    started = time.time_ns()
    identity.write_new(folder / 'command.json', {'argv': command, 'cwd': str(ROOT), 'startedEpochNs': started})
    process, failure = None, None
    try:
        with (folder / 'console.log').open('xb') as console:
            process = subprocess.Popen(command, cwd=ROOT, stdout=console, stderr=subprocess.STDOUT,
                                       start_new_session=True)
            deadline = time.monotonic() + timeout
            next_report = time.monotonic() + 30
            while process.poll() is None:
                if time.monotonic() >= deadline:
                    raise TimeoutError('Prespecified fork deadline exceeded')
                if time.monotonic() >= next_report:
                    print('  JVM still running; raw output preserved', flush=True)
                    next_report += 30
                time.sleep(.2)
            check(process.wait() == 0, 'JVM exited unsuccessfully')
    except BaseException as problem:
        failure = {'exception': type(problem).__name__, 'message': str(problem)}
        raise
    finally:
        if process is not None and process.poll() is None:
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=10)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
        identity.write_new(folder / 'process-result.json', {'exitCode': process.returncode if process else None,
            'startedEpochNs': started, 'finishedEpochNs': time.time_ns(), 'failure': failure})


def summary(runs, complete, errors):
    result = {'complete': complete, 'errors': errors, 'completedJvms': len(runs),
        'rawQueryCount': sum(len(r['samples']) for r in runs),
        'rawMeasuredQueryCount': sum(sum(s['stage'] == 'measurement' for s in r['samples']) for r in runs),
        'comparisonStatus': 'complete prespecified protocol' if complete else 'incomplete; no accepted comparison estimates',
        'ratioDefinition': 'Ratio of each fresh-JVM median of all five measured queries within the same matched round.',
        'comparisons': []}
    if not complete:
        return result
    indexed = {(r['round'], r['arm']): r for r in runs}
    for candidate, comparator in PAIRS:
        pairs = []
        for round_index in range(6):
            a, b = indexed[round_index, candidate], indexed[round_index, comparator]
            pairs.append({'round': round_index,
                'ratios': {k: a['medians'][k] / b['medians'][k] if b['medians'][k] else None for k in METRICS},
                'routeTierHistogramsEqual': a['routeTierHistogram'] == b['routeTierHistogram']})
        values = {k: [p['ratios'][k] for p in pairs if p['ratios'][k] is not None] for k in METRICS}
        result['comparisons'].append({'candidate': candidate, 'comparator': comparator, 'pairs': pairs,
            'medianRatios': {k: statistics.median(v) if v else None for k, v in values.items()},
            'ratioRanges': {k: [min(v), max(v)] if v else None for k, v in values.items()},
            'allSixLatencyRatiosFavorCandidate': all(p['ratios']['totalNs'] < 1 for p in pairs),
            'allRouteTierHistogramsEqual': all(p['routeTierHistogramsEqual'] for p in pairs)})
    return result


def execute(args):
    protocol_path = args.protocol.resolve(strict=True)
    protocol_sha = identity.sha(protocol_path)
    protocol, snapshots = validate_protocol(protocol_path)
    if args.validate_only:
        print('Frozen protocol/runtime validation passed; no JVM launched.')
        return
    check(args.slot_released and args.output is not None, 'Execution requires an exclusive slot and new output path')
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    (output / 'used-protocol.json').write_bytes(protocol_path.read_bytes())
    watched = {str(protocol_path): protocol_sha, str(Path(__file__)): protocol['driverSha256'],
               str(IDENTITY_FILE): protocol['identityHelperSha256']}
    for key in ('diagnosticEvidenceFile', 'commonHarnessDescriptorFile', 'freezeHelperFile'):
        watched[protocol[key]] = protocol[key + 'Sha256']
    for name, runtime in snapshots.items():
        consumed = output / 'runtime-identities' / name
        consumed.mkdir(parents=True)
        identity.write_new(consumed / 'runtime-descriptor.json', runtime['descriptor'])
        for key, path in runtime['inputs'].items():
            watched[str(path)] = identity.sha(path)
            (consumed / (key + '-' + path.name)).write_bytes(path.read_bytes())
    identity.write_new(output / 'preflight.json', {'protocolSha256': protocol_sha,
        'runtimeManifests': {name: r['manifest'] for name, r in snapshots.items()}, 'watchedFiles': watched})
    runs, errors, metadata_reference, route_reference = [], [], None, None
    for round_index, order in enumerate(protocol['balancedOrders']):
        if errors:
            break
        for position, arm in enumerate(order):
            folder = output / f'round-{round_index:02d}-{position:02d}-{arm}'
            folder.mkdir()
            arm_spec = protocol['armDefinitions'][arm]
            runtime, mode = snapshots[arm_spec['runtime']], arm_spec['transportMode']
            command = [JAVA, *JVM, '-D' + PROPERTY + '=' + mode, '-cp', runtime['classpath'], MAIN,
                '--arm=' + arm, '--source=' + runtime['descriptor']['sourceIdentity'],
                '--warmup=8', '--iterations=5', '--measurements=100', '--readings=10', '--width=12',
                '--statuses=2', '--unique-payloads=0', '--consumption=full',
                '--output=' + str(folder / 'samples.jsonl'), '--store=' + str(folder / 'store')]
            print(f'Running round {round_index + 1}/6, position {position + 1}/3: {arm}', flush=True)
            try:
                # These small checks run before process launch, outside all query timing windows.
                verified_file(protocol_path, protocol_sha)
                verified_file(Path(__file__), protocol['driverSha256'])
                verified_file(IDENTITY_FILE, protocol['identityHelperSha256'])
                verified_file(protocol['freezeHelperFile'], protocol['freezeHelperFileSha256'])
                check(identity.classpath_manifest(runtime['manifest'][0]['path']) == [runtime['manifest'][0]],
                      'Common uninstrumented harness changed before fork')
                run_fork(command, folder, protocol['timeoutSeconds'])
                metadata, samples, audit, measured, validation = validate_run(folder, arm, runtime, mode)
                normalized = normalized_metadata(metadata)
                if metadata_reference is None:
                    metadata_reference = normalized
                check(normalized == metadata_reference, 'Normalized input/JVM metadata differs between arms')
                measured_routes = route_histogram(measured)
                if route_reference is None:
                    route_reference = measured_routes
                same_route = measured_routes == route_reference
                runs.append({'round': round_index, 'position': position, 'arm': arm, 'runtime': arm_spec['runtime'],
                    'transportMode': mode, 'directory': str(folder), 'metadata': metadata, 'samples': samples,
                    'rootAudit': audit, 'validation': validation,
                    'medians': {k: statistics.median(s[k] for s in measured) for k in METRICS},
                    'counterMedians': {k: statistics.median(s['counters'][k] for s in measured)
                        for k, v in measured[0]['counters'].items() if isinstance(v, (int, float))},
                    'adjacencyLookupHits': [s['adjacency']['lookupHits'] for s in measured],
                    'routeTierHistogram': measured_routes,
                    'routeTierHistogramMatchesFirstFork': same_route})
                check(validation['targetQualified'], '; '.join(validation['targetQualificationReasons']))
                check(same_route, 'Measured AUTO route/tier histogram changed from the first qualified fork')
                print(f'  completed {len(runs)}/18; all 13 queries valid, target qualified', flush=True)
            except Exception as error:
                errors.append({'round': round_index, 'position': position, 'arm': arm, 'directory': str(folder),
                    'exception': type(error).__name__, 'message': str(error),
                    'policy': 'Preserve raw records and stop; no replacement, exclusions, extra rounds or forced routes'})
                print('  BLOCKED: ' + str(error), flush=True)
            (output / 'runs.json').write_text(json.dumps(runs, indent=2) + '\n')
            (output / 'summary.json').write_text(json.dumps(summary(runs, False, errors), indent=2) + '\n')
            if errors:
                break
    post = {'identityFilesUnchanged': all(Path(p).is_file() and identity.sha(p) == h for p, h in watched.items()),
            'runtimeIdentitiesUnchanged': {name: identity.classpath_manifest(r['classpath']) == r['manifest']
                                            for name, r in snapshots.items()}}
    identity.write_new(output / 'post-run-preservation.json', post)
    if not post['identityFilesUnchanged'] or not all(post['runtimeIdentitiesUnchanged'].values()):
        errors.append({'exception': 'IdentityMismatch', 'message': 'Runtime/protocol/driver/source evidence changed'})
    complete = len(runs) == 18 and not errors
    (output / 'summary.json').write_text(json.dumps(summary(runs, complete, errors), indent=2) + '\n')
    print(json.dumps({'output': str(output), 'complete': complete, 'completedJvms': len(runs), 'errors': errors}))
    if not complete:
        raise SystemExit(1)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--protocol', type=Path, required=True)
    parser.add_argument('--freeze-candidate', type=Path)
    parser.add_argument('--frozen-protocol', type=Path)
    parser.add_argument('--reviewed-production-patch-sha256')
    parser.add_argument('--output', type=Path)
    parser.add_argument('--validate-only', action='store_true')
    parser.add_argument('--slot-released', action='store_true')
    args = parser.parse_args()
    if args.freeze_candidate:
        check(args.frozen_protocol is not None and not args.validate_only and args.output is None,
              'Freezing needs only candidate descriptor and a new frozen protocol path')
        freeze_protocol(args)
    else:
        execute(args)


if __name__ == '__main__':
    main()
